51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    /**
60	     * Process-wide monotonically increasing sequence stamped onto each structured owner-created
61	     * audit event, so events can be totally ordered across creates.
62	     */
63	    private static final java.util.concurrent.atomic.AtomicInteger AUDIT_SEQ =
64	        new java.util.concurrent.atomic.AtomicInteger(0);
65	
66	    /** Serializes the immutable structured audit events to JSON. */
67	    private static final tools.jackson.databind.ObjectMapper AUDIT_MAPPER =
68	        new tools.jackson.databind.json.JsonMapper();
69	
70	    /**
71	     * Immutable structured audit event emitted (as JSON, on the {@code AUDIT} logger) for each
72	     * successful owner create. {@code seq} is the process-wide {@link #AUDIT_SEQ} counter, and
73	     * {@code customerCode} carries the owner's current primary identifier — the customerCode today,
74	     * and whatever replaces it later (e.g. once the customerCode is unified into the memberId, this
75	     * carries the memberId instead). The component order matches the JSON field order.
76	     */
77	    private record OwnerCreatedEvent(int seq, Integer ownerId, String customerCode,
78	        Integer membershipLevel, String event) {
79	    }
80	
81	    /** HTTP header carrying the caller-supplied idempotency key for create requests. */
82	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
83	
84	    /**
85	     * Remembers the owner created for each already-seen {@code Idempotency-Key}, so a repeated create
86	     * with the same key returns the originally created owner instead of creating a duplicate. Keyed by
87	     * the header value, valued by the created owner's id.
88	     */
89	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotentCreates =
90	        new java.util.concurrent.ConcurrentHashMap<>();
91	
