134	
135	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
136	     *  separated by '@', none of which contain whitespace or a second '@'. */
137	    private static final java.util.regex.Pattern EMAIL_PATTERN =
138	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
139	
140	    /** Disposable email domains that are not accepted as an owner's email. */
141	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
142	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
143	
144	    /**
145	     * Normalize the optional email: absent stays absent; when present it must be syntactically
146	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
147	     * domain is on the disposable-domain blocklist.
148	     */
149	    private boolean normalizeEmail(Owner owner) {
150	        String email = owner.getEmail();
151	        if (email == null || email.isEmpty()) {
152	            owner.setEmail(null);
153	            return true;
154	        }
155	        if (!EMAIL_PATTERN.matcher(email).matches()) {
156	            return false;
157	        }
158	        email = email.toLowerCase(java.util.Locale.ROOT);
159	        String domain = email.substring(email.indexOf('@') + 1);
160	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
161	            return false;
162	        }
163	        owner.setEmail(email);
164	        return true;
165	    }
166	
167	    /**
168	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
169	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
170	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
171	     *
172	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
173	     *         a valid E.164 number.
174	     */
175	    private static String toE164(String raw) {
176	        if (raw == null) {
177	            return null;
178	        }
179	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
180	        String digits;
181	        if (cleaned.startsWith("+")) {
182	            digits = cleaned.substring(1);
183	        } else {
184	            if (cleaned.startsWith("0")) {
185	                cleaned = cleaned.substring(1);
186	            }
187	            digits = "61" + cleaned;
188	        }
189	        if (!digits.matches("\\d{8,15}")) {
190	            return null;
191	        }
192	        return "+" + digits;
193	    }
194	
195	    /**
196	     * Validate the national-number length of a canonical E.164 string against its country code:
197	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
198	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
199	     * string produced by {@link #toE164}.
200	     *
201	     * @return {@code true} when the national-number length is correct for the country code.
202	     */
203	    private static boolean hasValidNationalLength(String e164) {
204	        String digits = e164.substring(1);
205	        if (digits.startsWith("61")) {
206	            return digits.length() - 2 == 9;
207	        }
208	        if (digits.startsWith("1")) {
209	            return digits.length() - 1 == 10;
210	        }
211	        return true;
212	    }
213	
214	    /**
215	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
216	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
217	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
218	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
219	     * numbers are used, so the base code is a pure function of the owner's region-and-hash identity.
220	     * When that base code collides with an existing owner's customerCode, {@code -<n>} is appended with
221	     * the smallest {@code n} of 2 or more that makes it unique, returning the de-duplicated code.
222	     */
223	    private String customerCodeFor(Owner owner) {
224	        String region = ownerMapper.regionFromPostcode(owner);
225	        if (region == null) {
226	            region = "UNKNOWN";
227	        }
228	        String base = region + "-" + hash8(owner.getTelephone(), owner.getLastName());
229	
230	        java.util.Set<String> existingCodes = new java.util.HashSet<>();
231	        for (Owner existing : this.clinicService.findAllOwners()) {
232	            String code = existing.getCustomerCode();
233	            if (code != null) {
234	                existingCodes.add(code);
235	            }
236	        }
237	        if (!existingCodes.contains(base)) {
238	            return base;
239	        }
240	        for (int n = 2; ; n++) {
241	            String candidate = base + "-" + n;
242	            if (!existingCodes.contains(candidate)) {
243	                return candidate;
244	            }
245	        }
246	    }
247	
248	    /**
249	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
250	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
251	     */
252	    private static String hash8(String normalizedTelephone, String lastName) {
253	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
254	            + (lastName == null ? "" : lastName);
255	        try {
256	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
257	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
258	            StringBuilder sb = new StringBuilder(8);
259	            for (int i = 0; i < 4; i++) {
260	                sb.append(String.format("%02X", digest[i]));
261	            }
262	            return sb.toString();
263	        }
264	        catch (java.security.NoSuchAlgorithmException e) {
265	            throw new IllegalStateException(e);
266	        }
267	    }
268	
269	    /** Common street-type abbreviations expanded during address normalization. */
270	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
271	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
272	
273	    /**
274	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
275	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
276	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
277	     */
278	    private static String normalizeAddress(String value) {
279	        if (value == null) {
280	            return "";
281	        }
282	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
283	        if (collapsed.isEmpty()) {
284	            return "";
285	        }
286	        String[] tokens = collapsed.split(" ");
287	        StringBuilder sb = new StringBuilder(collapsed.length());
288	        for (int i = 0; i < tokens.length; i++) {
289	            if (i > 0) {
290	                sb.append(' ');
291	            }
292	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
293	        }
294	        return sb.toString();
295	    }
296	
297	    /**
298	     * Resolve and normalize the owner's postal address, preferring the structured form.
299	     *
300	     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
301	     * optional {@code addressLine2}, are normalized in place and the composed address is the
302	     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
303	     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
304	     * {@code null} when neither form yields a non-empty address, so the caller can reject the
305	     * request.
306	     */
307	    private String composeAddress(Owner owner) {
308	        String line1 = owner.getAddressLine1();
309	        if (line1 != null && !line1.isBlank()) {
310	            String normalizedLine1 = normalizeAddress(line1);
311	            owner.setAddressLine1(normalizedLine1);
312	            String line2 = owner.getAddressLine2();
313	            if (line2 != null && !line2.isBlank()) {
314	                String normalizedLine2 = normalizeAddress(line2);
315	                owner.setAddressLine2(normalizedLine2);
316	                return normalizedLine1 + " " + normalizedLine2;
317	            }
318	            owner.setAddressLine2(null);
319	            return normalizedLine1.isEmpty() ? null : normalizedLine1;
320	        }
321	        String normalized = normalizeAddress(owner.getAddress());
322	        return normalized.isEmpty() ? null : normalized;
323	    }
324	
325	    /**
326	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
327	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
328	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
329	     */
330	    private static String normalizeForHousehold(String value) {
331	        if (value == null) {
332	            return "";
333	        }
334	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
335	    }
336	
337	    /**
338	     * Return the owners that already share this owner's household, i.e. resolve to the same
339	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
340	     * postcode).
341	     */
342	    private List<Owner> householdMembers(Owner owner) {
343	        String householdId = householdIdFor(owner);
344	        List<Owner> members = new java.util.ArrayList<>();
345	        for (Owner existing : this.clinicService.findAllOwners()) {
346	            if (existing.isDeleted()) {
347	                continue;
348	            }
349	            if (householdId.equals(householdIdFor(existing))) {
350	                members.add(existing);
351	            }
352	        }
353	        return members;
354	    }
355	
356	    /**
357	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
358	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
359	     */
360	    private boolean sharesHouseholdWithExisting(Owner owner) {
361	        return !householdMembers(owner).isEmpty();
362	    }
363	
364	    /**
365	     * Count the existing owners that share this owner's first name and last name, compared
366	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
367	     */
368	    private int namesakeCount(Owner owner) {
369	        String firstName = owner.getFirstName();
370	        String lastName = owner.getLastName();
371	        int count = 0;
372	        for (Owner existing : this.clinicService.findAllOwners()) {
373	            if (firstName != null && lastName != null
374	                && firstName.equalsIgnoreCase(existing.getFirstName())
375	                && lastName.equalsIgnoreCase(existing.getLastName())) {
376	                count++;
377	            }
378	        }
379	        return count;
380	    }
381	
382	    /**
383	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
384	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
385	     * Because it is a pure function of the last name and postcode, every owner in the same household
386	     * deterministically resolves to the same value.
387	     */
388	    private static String householdIdFor(Owner owner) {
389	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
390	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
391	        try {
392	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
393	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
394	            StringBuilder sb = new StringBuilder(12);
395	            for (int i = 0; i < 6; i++) {
396	                sb.append(String.format("%02X", digest[i]));
397	            }
398	            return sb.toString();
399	        }
400	        catch (java.security.NoSuchAlgorithmException e) {
401	            throw new IllegalStateException(e);
402	        }
403	    }
404	
405	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
406	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
407	        "NSW", new int[] {2000, 2099},
408	        "VIC", new int[] {3000, 3099},
409	        "QLD", new int[] {4000, 4099});
410	
411	    /**
412	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
413	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
414	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
415	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
416	     * postcode.
417	     */
418	    private boolean isPostcodeValid(Owner owner) {
419	        String postcode = owner.getPostcode();
420	        if (postcode == null || postcode.isEmpty()) {
421	            return true;
422	        }
423	        if (!postcode.matches("\\d{4}")) {
424	            return false;
425	        }
426	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
427	        if (range == null) {
428	            return true;
429	        }
430	        int value = Integer.parseInt(postcode);
431	        return value >= range[0] && value <= range[1];
432	    }
433	
434	    /**
435	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
436	     * "possible duplicate": one whose last name shares this owner's {@link Owner#soundex(String)
437	     * soundex} and whose postcode matches, yet whose whole {@link Owner#getIdentityKey() identityKey}
438	     * differs (so it is not a hard duplicate). When several match, the one with the smallest id is
439	     * chosen so the result is deterministic. Returns {@code null} when the owner has no postcode or no
440	     * such existing owner exists.
441	     */
442	    private Owner possibleDuplicateOf(Owner owner) {
443	        String lastName = owner.getLastName();
444	        String postcode = owner.getPostcode();
445	        if (lastName == null || postcode == null || postcode.isEmpty()) {
446	            return null;
447	        }
448	        String soundex = Owner.soundex(lastName);
449	        String identityKey = owner.getIdentityKey();
450	        Owner match = null;
451	        for (Owner existing : this.clinicService.findAllOwners()) {
452	            if (soundex.equals(Owner.soundex(existing.getLastName()))
453	                && postcode.equals(existing.getPostcode())
454	                && !identityKey.equals(existing.getIdentityKey())) {
455	                if (match == null || (existing.getId() != null && match.getId() != null
456	                    && existing.getId() < match.getId())) {
457	                    match = existing;
458	                }
459	            }
460	        }
461	        return match;
462	    }
463	
464	    /** Maximum number of owners permitted in a single city. */
465	    private static final int CITY_CAPACITY = 50;
466	
467	    /**
468	     * Number of owners already in a city at or beyond which a capacity warning is flagged (the city
469	     * is approaching the {@link #CITY_CAPACITY} hard limit). A city holding 40-49 owners warns.
470	     */
471	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
472	
473	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
474	    private static final int DAILY_CREATE_LIMIT = 100;
475	
476	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
477	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
478	
479	    /**
480	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
481	     * Used to enforce the per-city capacity on create (before this owner is saved).
482	     */
483	    private int cityOwnerCount(Owner owner) {
484	        String city = owner.getCity();
485	        int count = 0;
486	        for (Owner existing : this.clinicService.findAllOwners()) {
487	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
488	                count++;
489	            }
490	        }
491	        return count;
492	    }
493	
494	    /** Fixed public holidays the business-day roll skips. */
495	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
496	        java.time.LocalDate.parse("2026-01-01"),
497	        java.time.LocalDate.parse("2026-01-26"),
498	        java.time.LocalDate.parse("2026-04-25"),
499	        java.time.LocalDate.parse("2026-12-25"),
500	        java.time.LocalDate.parse("2026-12-28"));
501	
502	    /**
503	     * Roll a registration date forward onto a business day: any Saturday, Sunday or listed public
504	     * holiday is advanced one day at a time until a non-holiday weekday is reached; a date that is
505	     * already a non-holiday weekday is returned unchanged. Applied to the effective registration date
506	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
507	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
508	     */
509	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
510	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
511	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
512	            || PUBLIC_HOLIDAYS.contains(date)) {
513	            date = date.plusDays(1);
514	        }
515	        return date;
516	    }
517	
518	    /**
519	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
520	     * per-day create limit on create (before this owner is saved).
521	     */
522	    private int ownersRegisteredOn(java.time.LocalDate day) {
523	        int count = 0;
524	        for (Owner existing : this.clinicService.findAllOwners()) {
525	            if (day.equals(existing.getRegistrationDate())) {
526	                count++;
527	            }
528	        }
529	        return count;
530	    }
531	
532	    /**
533	     * The {@code Idempotency-Key} header of the request currently being handled, or {@code null} when
534	     * the header is absent, blank or no servlet request is bound to the calling thread. The generated
535	     * {@link OwnersApi#addOwner} signature carries no header parameter, so it is read from the bound
536	     * request context.
537	     */
538	    private static String currentIdempotencyKey() {
539	        org.springframework.web.context.request.RequestAttributes attrs =
540	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
541	        if (attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs) {
542	            String key = servletAttrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
543	            if (key != null && !key.isBlank()) {
544	                return key;
545	            }
546	        }
547	        return null;
548	    }
549	
550	    /**
551	     * The owner's current primary identifier, carried by the structured owner-created audit event.
552	     * Today this is the {@code customerCode}; when the primary identifier is later unified into the
553	     * memberId this returns that instead, so the emitted event automatically switches identifier
554	     * without changing the emission site.
555	     */
556	    private String primaryIdentifier(Owner owner) {
557	        return owner.getCustomerCode();
558	    }
559	
560	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
561	    @Override
562	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
563	        HttpHeaders headers = new HttpHeaders();
564	        // Idempotent create: when this request carries an Idempotency-Key we have already seen, return
565	        // the owner originally created for that key (200) instead of creating a duplicate.
566	        String idempotencyKey = currentIdempotencyKey();
567	        if (idempotencyKey != null) {
568	            Integer existingId = idempotentCreates.get(idempotencyKey);
569	            if (existingId != null) {
570	                Owner existing = this.clinicService.findOwnerById(existingId);
571	                if (existing != null) {
572	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
573	                }
574	            }
575	        }
576	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
577	        if (!isPostcodeValid(owner)) {
578	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
579	        }
580	        String telephone = toE164(owner.getTelephone());
581	        if (telephone == null || !hasValidNationalLength(telephone)) {
582	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
583	        }
584	        if (!normalizeEmail(owner)) {
585	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
586	        }
587	        String address = composeAddress(owner);
588	        if (address == null) {
589	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
590	        }
591	        owner.setAddress(address);
592	        owner.setTelephone(telephone);
593	        if (owner.getRegistrationDate() != null
594	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
595	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
596	        }
597	        java.time.LocalDate registrationDate = toBusinessDay(
598	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
599	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
600	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
601	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
602	        }
603	        int cityOwnerCount = cityOwnerCount(owner);
604	        if (cityOwnerCount >= CITY_CAPACITY) {
605	            return new ResponseEntity<>(HttpStatus.CONFLICT);
606	        }
607	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
608	        // owners with the same last name and postcode automatically share it. The link is no longer
609	        // created by copying an existing owner's id around.
610	        owner.setHouseholdId(householdIdFor(owner));
611	        List<Owner> householdMembers = householdMembers(owner);
612	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
613	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
614	
615	        // Hard duplicate: a new owner whose identityKey (SHA-256 over telephone|email|soundex(lastName))
616	        // equals an existing, non-deleted owner's is the same identity and is always rejected. This is
617	        // now the single duplicate check: because the telephone is part of the key, two owners with the
618	        // same last name and postcode but different telephones no longer collide here and instead fall
619	        // through to the possible-duplicate (soft-match) flagging below.
620	        String identityKey = owner.getIdentityKey();
621	        for (Owner existing : this.clinicService.findAllOwners()) {
622	            if (existing.isDeleted()) {
623	                continue;
624	            }
625	            if (identityKey.equals(existing.getIdentityKey())) {
626	                return new ResponseEntity<>(HttpStatus.CONFLICT);
627	            }
628	        }
629	        // Household member: another owner already shares this (last name, postcode) household. This
630	        // is no longer rejected as a duplicate — an exact byte-for-byte identity match is already
631	        // caught above, and a distinct additional household member is admitted with its membership
632	        // level capped (see below) at one above the current household maximum. The 'sharesHousehold'
633	        // flag now only signals that the caller vouches for the member, suppressing the
634	        // possible-duplicate flagging below.
635	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner whose
636	        // last name shares an existing owner's soundex and postcode but whose identityKey differs.
637	        if (declaredHouseholdMember) {
638	            owner.setPossibleDuplicate(false);
639	            owner.setPossibleDuplicateOf(null);
640	        }
641	        else {
642	            Owner duplicateOf = possibleDuplicateOf(owner);
643	            owner.setPossibleDuplicate(duplicateOf != null);
644	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
645	        }
646	        owner.setNamesakeCount(namesakeCount(owner));
647	        owner.setHouseholdSize(householdMembers.size() + 1);
648	        // Level ceiling: a new owner's membershipLevel cannot exceed one above the current maximum
649	        // membershipLevel among their existing household members. With no existing member, no cap.
650	        if (householdMembers.isEmpty()) {
651	            owner.setMembershipLevelCap(null);
652	        }
653	        else {
654	            int maxHouseholdLevel = householdMembers.stream()
655	                .mapToInt(member -> ownerMapper.membershipLevel(member))
656	                .max()
657	                .getAsInt();
658	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
659	        }
660	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
661	        owner.setCapacityWarning(cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD);
662	        owner.setRegistrationDate(registrationDate);
663	        owner.setCustomerCode(customerCodeFor(owner));
664	        this.clinicService.saveOwner(owner);
665	        if (idempotencyKey != null) {
666	            idempotentCreates.put(idempotencyKey, owner.getId());
667	        }
668	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
669	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
670	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
671	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
672	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner), "OWNER_CREATED");
673	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
674	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
675	        headers.setLocation(UriComponentsBuilder.newInstance()
676	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
677	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
678	    }
679	
680	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
681	    @Override
682	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
683	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
684	        if (currentOwner == null) {
685	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
686	        }
687	        currentOwner.setAddress(ownerFieldsDto.getAddress());
688	        currentOwner.setCity(ownerFieldsDto.getCity());
689	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
690	        currentOwner.setLastName(ownerFieldsDto.getLastName());
691	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
692	        currentOwner.setEmail(ownerFieldsDto.getEmail());
693	        if (!normalizeEmail(currentOwner)) {
694	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
695	        }
696	        this.clinicService.saveOwner(currentOwner);
697	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
698	    }
699	
700	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
701	    @Transactional
702	    @Override
703	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
704	        Owner owner = this.clinicService.findOwnerById(ownerId);
705	        if (owner == null) {
706	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
707	        }
708	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
709	        owner.setDeleted(true);
710	        this.clinicService.saveOwner(owner);
711	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
712	    }
713	
714	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
715	    @Override
716	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
717	        Owner owner = this.clinicService.findOwnerById(ownerId);
718	        if (owner == null) {
719	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
720	        }
721	        HttpHeaders headers = new HttpHeaders();
722	        Pet pet = petMapper.toPet(petFieldsDto);
723	        owner.setId(ownerId);
724	        pet.setOwner(owner);
725	        pet.getType().setName(null);
726	        this.clinicService.savePet(pet);
727	        PetDto petDto = petMapper.toPetDto(pet);
728	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
729	            .buildAndExpand(pet.getId()).toUri());
730	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
731	    }
732	
733	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
734	    @Override
735	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
736	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
737	        if (currentOwner != null) {
738	            Pet currentPet = this.clinicService.findPetById(petId);
739	            if (currentPet != null) {
740	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
741	                currentPet.setName(petFieldsDto.getName());
742	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
743	                this.clinicService.savePet(currentPet);
744	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
745	            }
746	        }
747	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
748	    }
749	
750	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
751	    @Override
752	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
753	        HttpHeaders headers = new HttpHeaders();
754	        Visit visit = visitMapper.toVisit(visitFieldsDto);
755	        Pet pet = new Pet();
756	        pet.setId(petId);
757	        visit.setPet(pet);
758	        this.clinicService.saveVisit(visit);
759	        VisitDto visitDto = visitMapper.toVisitDto(visit);
760	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
761	            .buildAndExpand(visit.getId()).toUri());
762	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
763	    }
764	
765	
766	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
767	    @Override
768	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
769	        Owner owner = this.clinicService.findOwnerById(ownerId);
770	        if (owner != null) {
771	            Pet pet = owner.getPet(petId);
772	            if (pet != null) {
773	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
774	            }
775	        }
776	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
777	    }
778	}
