29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
32	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * Derives the owner's salutation: the {@code title} followed by a single space and the last
40	     * name (e.g. {@code DR who}), or just the last name when no title is given (absent, empty or
41	     * blank).
42	     */
43	    default String salutation(Owner owner) {
44	        String lastName = owner.getLastName();
45	        String title = owner.getTitle();
46	        if (title == null || title.isBlank()) {
47	            return lastName;
48	        }
49	        return title + " " + lastName;
50	    }
51	
52	    /**
53	     * Formats the stored E.164 {@code telephone} for humans: the {@code '+'} and country code, a
54	     * space, then the national digits grouped in threes (e.g. {@code +61412345678} -&gt;
55	     * {@code +61 412 345 678}). The country code is taken as {@code 61} (Australia) or {@code 1}
56	     * (NANP) when recognised, otherwise a single leading digit. Returns {@code null} when the
57	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164
58	     * number.
59	     */
60	    default String telephoneDisplay(Owner owner) {
61	        String telephone = owner.getTelephone();
62	        if (telephone == null || telephone.isEmpty()) {
63	            return null;
64	        }
65	        if (!telephone.startsWith("+") || !telephone.substring(1).matches("\\d+")) {
66	            return telephone;
67	        }
68	        String digits = telephone.substring(1);
69	        int countryCodeLength;
70	        if (digits.startsWith("61")) {
71	            countryCodeLength = 2;
72	        }
73	        else if (digits.startsWith("1")) {
74	            countryCodeLength = 1;
75	        }
76	        else {
77	            countryCodeLength = 1;
78	        }
79	        String countryCode = digits.substring(0, countryCodeLength);
80	        String national = digits.substring(countryCodeLength);
81	        StringBuilder grouped = new StringBuilder();
82	        for (int i = 0; i < national.length(); i++) {
83	            if (i > 0 && i % 3 == 0) {
84	                grouped.append(' ');
85	            }
86	            grouped.append(national.charAt(i));
87	        }
88	        return "+" + countryCode + (national.isEmpty() ? "" : " " + grouped);
89	    }
90	
91	    /**
92	     * Derives the owner's age band from {@code birthDate} measured against {@code registrationDate}:
93	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older.
94	     * Returns {@code null} when no birthDate is recorded. When the registrationDate is absent (e.g.
95	     * legacy records) the current date is used as the reference point.
96	     */
97	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
98	        java.time.LocalDate birthDate = owner.getBirthDate();
99	        if (birthDate == null) {
100	            return null;
101	        }
102	        java.time.LocalDate reference = owner.getRegistrationDate() != null
103	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
104	        int age = java.time.Period.between(birthDate, reference).getYears();
105	        if (age < 18) {
106	            return OwnerDto.AgeBandEnum.MINOR;
107	        }
108	        if (age < 65) {
109	            return OwnerDto.AgeBandEnum.ADULT;
110	        }
111	        return OwnerDto.AgeBandEnum.SENIOR;
112	    }
113	
114	    /**
115	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is
116	     * present, otherwise {@code PHONE}.
117	     */
118	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
119	        String email = owner.getEmail();
120	        if (email != null && !email.isEmpty()) {
121	            return OwnerDto.ContactPreferenceEnum.EMAIL;
122	        }
123	        return OwnerDto.ContactPreferenceEnum.PHONE;
124	    }
125	
126	    /**
127	     * Derives the owner's locality (region) from the region-and-hash identity: it is the
128	     * {@code <REGION>} segment of the customerCode ({@code <REGION>-<HASH8>}), i.e. the region
129	     * derived from the postcode at create time. When the customerCode is absent or malformed
130	     * (e.g. legacy records), it falls back to the postcode range and then the fixed city-to-region
131	     * table, returning {@code UNKNOWN} when neither source resolves.
